$uid=(int)$_SESSION['user_id'];$role=$_SESSION['role'];if($role==='teacher'){header('Location: academics.php');exit;}$labels=['system_admin'=>['sub_admin','admin','director'],'sub_admin'=>['admin','director'],'admin'=>['director'],'director'=>['sub_director','headteacher','head_academic','assistant_academic','examination_officer','teacher','driver','hr','storekeeper'],'sub_director'=>['headteacher','head_academic','assistant_academic','examination_officer','teacher','driver','hr','storekeeper'],'headteacher'=>['teacher']];$allowed=$labels[$role]??[];$names=['system_admin'=>'System admin','sub_admin'=>'Sub system admin','admin'=>'Admin','director'=>'Director','sub_director'=>'Sub director','headteacher'=>'Head of school','head_academic'=>'Head of academics','assistant_academic'=>'Assistant academics','examination_officer'=>'Examination officer','teacher'=>'Teacher','driver'=>'Driver','hr'=>'HR','storekeeper'=>'Stores'];$error='';$db=db();
if(in_array($role,['system_admin','sub_admin'],true))$schools=$db->query('SELECT id,name FROM schools ORDER BY name')->fetchAll();else{$q=$db->prepare('SELECT s.id,s.name FROM schools s JOIN school_memberships m ON m.school_id=s.id WHERE m.user_id=? ORDER BY s.name');$q->execute([$uid]);$schools=$q->fetchAll();}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim((string)($_POST['name']??''));$identifier=strtolower(trim((string)($_POST['identifier']??$_POST['email']??'')));$email=filter_var($identifier,FILTER_VALIDATE_EMAIL)?$identifier:null;$username=$email?null:$identifier;$newRole=(string)($_POST['role']??'');$school=(int)($_POST['school_id']??0);$phone=trim((string)($_POST['phone']??''));if(!$allowed){http_response_code(403);exit('You cannot create accounts.');}if($name===''||($email===null&&!preg_match('/^[a-z0-9._-]{3,60}$/',$username))||!in_array($newRole,$allowed,true)||strlen($phone)>30||($newRole==='director'&&$phone===''))$error='Enter a name, valid sign-in ID and role; a director needs a phone number.';elseif($school&&!array_filter($schools,fn($s)=>(int)$s['id']===$school))$error='Choose a school within your access.';elseif(!in_array($newRole,['system_admin','sub_admin','admin','director'],true)&&!$school)$error='Choose a school for this account.';else{try{$dupe=$db->prepare('SELECT id FROM users WHERE email=? OR username=? LIMIT 1');$dupe->execute([$identifier,$identifier]);if($dupe->fetch())throw new DomainException('That sign-in ID is already in use.');$password=rtrim(strtr(base64_encode(random_bytes(18)),'+/','-_'),'=');$db->beginTransaction();$force=in_array($newRole,['system_admin','sub_admin','admin','director','sub_director','headteacher'],true);$q=$db->prepare('INSERT INTO users(name,phone,email,username,password_hash,role,must_change_password) VALUES(?,?,?,?,?,?,?)');$q->execute([$name,$newRole==='director'?($phone?:null):($phone?:null),$email,$username,password_hash($password,PASSWORD_DEFAULT),$newRole,$force]);$newId=(int)$db->lastInsertId();if($school){$q=$db->prepare("INSERT INTO school_memberships(school_id,user_id,scope) VALUES(?,?,'member')");$q->execute([$school,$newId]);}$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id) VALUES(?,?,?,?)');$q->execute([$uid,'create','user',$newId]);$db->commit();$_SESSION['created_account_credentials']=['name'=>$name,'identifier'=>$identifier,'password'=>$password];header('Location: team.php');exit;}catch(Throwable $ex){if($db->inTransaction())$db->rollBack();$error=$ex instanceof DomainException?$ex->getMessage():'Account could not be created. Confirm the database schema is current.';}}}
