tus"><strong>Account created for <?=e($credential['name'])?>.</strong> Copy and share these credentials securely; the temporary password is shown once.<br>Sign in as: <strong><?=e($credential['identifier']??$credential['email']??'')?></strong><br>Temporary password: <code id="temp-pass"><?=e($credential['password'])?></code> <button class="button" id="copy-pass" type="button">Copy password</button></div><?php endif;?><?php if($allowed):?><section class="note-create"><div class="section-heading"><div><div class="eyebrow">NEW ACCOUNT</div><h2>Invite a team member</h2></div></div><p class="muted note-intro">A secure temporary password is generated automatically.</p><form method="post" class="note-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><div><label for="name">Full name</label><input id="name" name="name" required maxlength="140"></div><div><label for="identifier">Email or username</label><input id="identifier" name="identifier" type="text" required maxlength="190" autocomplete="username"></div><div><label for="role">Role</label><select id="role" name="role" required><option value="">Choose role</option><?php foreach($allowed as $r):?><option value="<?=e($r)?>"><?=e($names[$r])?></option><?php endforeach;?></select></div><div data-director-phone hidden><label for="director-phone">Director phone number</label><input id="director-phone" name="phone" type="tel" maxlength="30" autocomplete="tel"><small class="muted">Required when registering a director.</small></div><?php if($schools):?><?php if($role==='headteacher'):?><?=render_school_select('school',$schools)?><?php else:?><div><label for="school">School access</label><select id="school" name="school_id"><option value="">No school assigned</option><?php foreach($schools as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?></option><?php endforeach;?></select></div><?php endif;?><?php endif;?></div><button class="button primary" type="submit">Create account</button></form></section><?php endif;?><section class="content-section"><div class="section-heading"><div><div class="eyebrow">DIRECTORY</div><h2>Team members</h2></div><span class="count-pill" id="team-count"><?=count($members)?> team members</span></div><div class="team-filters"><div><label for="team-search">Search team</label><input type="search" id="team-search" placeholder="Name, sign-in ID or school" autocomplete="off"></div><div><label for="team-role-filter">Role</label><select id="team-role-filter"><option value="">All roles</option><?php foreach($directoryNames as $roleKey=>$roleLabel):?><option value="<?=e($roleKey)?>"><?=e($roleLabel)?></option><?php endforeach;?></select></div><div><label for="team-status-filter">Status</label><select id="team-status-filter"><option value="">All statuses</option><option value="active">Active</option><option value="disabled">Disabled</option></select></div><p class="muted" id="team-filter-status" role="status" aria-live="polite"></p></div><?php if($members):?><div class="table-wrap"><table><thead><tr><th>Name</th><th>Sign-in ID</th><th>Role</th><th>School</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($members as $m):?><tr data-team-row data-role="<?=e($m['role'])?>" data-status="<?=e($m['status'])?>"><td><?=e($m['name'])?></td><td><?=e($m['email']?:($m['username']??'No email'))?></td><td><?=e($names[$m['role']]??$m['role'])?></td><td><?=e($m['schools']??$m['school']??'System wide')?></td><td><?=e(ucfirst($m['status']))?></td><td><details class="row-actions"><summary class="button">Actions</summary><div class="action-menu"><?php if(in_array($role,['system_admin','sub_admin'],true)&&(int)$m['id']!==$uid&&$m['role']!=='system_admin'):?><a href="team_analyze.php?id=<?=$m['id']?>">Analyze</a><?php endif;?><form method="post" action="team_action.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$m['id']?>"><input type="hidden" name="action" value="reset"><button type="submit">Reset password</button></form><?php if(in_array($role,['system_admin','sub_admin'],true)&&$m['role']!=='system_admin'&&(int)$m['id']!==$uid):?><form method="post" action="team_action.php" onsubmit="return confirm('Suspend or reactivate this account?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$m['id']?>"><input type="hidden" name="action" value="suspend"><button type="submit"><?=$m['status']==='active'?'Suspend':'Reactivate'?></button></form><?php endif;?></div></details></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><h3>No team members yet</h3><p>Accounts will appear here as your team grows.</p></div><?php endif;?><div id="team-no-matches" class="empty-state" hidden><h3>No matching team members</h3><p>Adjust your search or filters to see more results.</p></div></section></div></main></div><script>document.querySelector('#copy-pass')?.addEventListener('click',async e=>{await navigator.clipboard.writeText(document.querySelector('#temp-pass').textContent);e.currentTarget.textContent='Copied'});document.querySelectorAll('[data-team-row]').forEach(row=>{row.dataset.searchText=row.textContent.toLocaleLowerCase()});document.querySelectorAll('details.row-actions').forEach(menu=>menu.addEventListener('toggle',()=>{if(menu.open)document.querySelectorAll('details.row-actions[open]').forEach(other=>{if(other!==menu)other.open=false})}));const search=document.querySelector('#team-search'),roleFilter=document.querySelector('#team-role-filter'),statusFilter=document.querySelector('#team-status-filter'),teamRows=[...document.querySelectorAll('[data-team-row]')],teamCount=document.querySelector('#team-count'),filterStatus=document.querySelector('#team-filter-status');function filterTeam(){const term=(search?.value||'').trim().toLocaleLowerCase(),roleValue=roleFilter?.value||'',statusValue=statusFilter?.value||'';let visible=0;teamRows.forEach(row=>{const show=(!term||row.dataset.searchText.includes(term))&&(!roleValue||row.dataset.role===roleValue)&&(!statusValue||row.dataset.status===statusValue);row.hidden=!show;if(show)visible++});if(teamCount)teamCount.textContent=visible+' team members';if(filterStatus)filterStatus.textContent=visible+' of '+teamRows.length+' team members shown';const noMatches=document.querySelector('#team-no-matches');if(noMatches)noMatches.hidden=visible!==0||teamRows.length===0}[search,roleFilter,statusFilter].forEach(control=>control?.addEventListener(control===search?'input':'change',filterTeam));const roleSelect=document.querySelector('#role'),directorPhone=document.querySelector('[data-director-phone]'),phoneInput=document.querySelector('#director-phone');function toggleDirectorPhone(){const show=roleSelect?.value==='director';if(directorPhone)directorPhone.hidden=!show;if(phoneInput)phoneInput.required=!!show}roleSelect?.addEventListener('change',toggleDirectorPhone);toggleDirectorPhone();</script></body></html>
